-- =====================================================================
-- ElisCaretex V2
-- Migration: 202608080003_legacy_production_roster_and_leave_history_import.sql — corrected v3
-- Source: Weekly Shift Roster_db (1).xlsx
-- Source batch: LEGACY_ROSTER_20260808
--
-- Purpose:
--   Import legacy Production Roster snapshots as immutable published history
--   and migrate legacy Day Off / Holiday request history with provenance.
--
-- Import policy:
--   * Official roster history is limited to weeks 2026-02-16 through 2026-08-03.
--   * Future legacy roster rows are NOT imported as published V2 rosters.
--   * The source workbook stored many default roster cells implicitly. This
--     migration uses the reconstructed source matrix produced from the legacy
--     reader rule: Monday-Saturday default WORKING; Sunday default OFF.
--   * Numeric legacy user keys take precedence over legacy name keys, matching
--     the legacy application's read behavior.
--   * Existing V2 published rosters are never overwritten.
--   * Existing equivalent V2 leave requests are never duplicated.
--   * Two legacy Day Off requests with no explicit decision are imported as
--     APPROVED from high-confidence roster evidence; this inference is clearly
--     labelled in immutable event history.
--   * Legacy GM configuration changes are preserved in the source workbook/
--     import report but DO NOT overwrite V2 governance settings.
--   * The legacy format did not store an Area for Supervisor, Cleaner or
--     Support Role sections. V2 requires an area for working assignments.
--     FINISH is therefore used only as a technical compatibility area for
--     those role-only historical rows; display_section_code preserves the
--     authoritative legacy section.
-- =====================================================================

begin;

create schema if not exists staging;
revoke all on schema staging from public, anon, authenticated;

do $$
begin
  if to_regclass('public.staff_members') is null
     or to_regclass('public.production_roster_versions') is null
     or to_regclass('public.production_roster_entries') is null
     or to_regclass('public.production_roster_events') is null
     or to_regclass('public.production_roster_leave_requests') is null
     or to_regclass('public.production_roster_leave_request_events') is null
     or to_regclass('public.production_roster_leave_gm_reviews') is null then
    raise exception 'Required ElisCaretex V2 Production Roster / Leave tables are missing.';
  end if;

  if not exists (
    select 1 from information_schema.columns
    where table_schema='public' and table_name='staff_members' and column_name='legacy_user_id'
  ) then
    raise exception 'Staff Master legacy_user_id mapping is required before importing legacy roster history.';
  end if;
end;
$$;

create table if not exists staging.legacy_production_roster_source (
  source_batch text not null,
  source_file text not null,
  week_start date not null,
  shift_code text not null,
  include_sunday boolean not null,
  legacy_version integer not null,
  source_updated_at timestamptz,
  source_updated_by text,
  source_entry_count integer not null,
  implicit_default_count integer not null,
  source_payload jsonb not null,
  import_status text not null default 'PENDING',
  imported_roster_version_id uuid,
  import_note text,
  imported_at timestamptz,
  primary key (source_batch, week_start, shift_code)
);

create table if not exists staging.legacy_leave_request_source (
  source_batch text not null,
  source_file text not null,
  legacy_request_id text not null,
  target_leave_request_id uuid not null,
  legacy_user_id integer not null,
  staff_name text not null,
  request_type text not null,
  start_date date not null,
  end_date date not null,
  reason text,
  submitted_at timestamptz not null,
  final_status text not null,
  decision_source text,
  decision_actor text,
  reviewed_at timestamptz,
  review_note text,
  decision_basis text not null,
  requires_general_manager boolean not null,
  gm_threshold_days_snapshot integer not null,
  source_events jsonb not null,
  roster_evidence jsonb not null default '[]'::jsonb,
  gm_review jsonb,
  import_status text not null default 'PENDING',
  imported_leave_request_id uuid,
  import_note text,
  imported_at timestamptz,
  primary key (source_batch, legacy_request_id)
);

alter table staging.legacy_production_roster_source enable row level security;
alter table staging.legacy_leave_request_source enable row level security;
revoke all on staging.legacy_production_roster_source from public, anon, authenticated;
revoke all on staging.legacy_leave_request_source from public, anon, authenticated;

create or replace function staging.legacy_roster_status(p_code text)
returns text
language sql immutable set search_path=pg_temp
as $$
  select case p_code
    when 'W' then 'WORKING'
    when 'O' then 'OFF'
    when 'H' then 'HOLIDAY'
    when 'C' then 'WORKING'
    when 'Q' then 'QUALITY_ANALYSIS'
    when 'S' then 'SICK'
    when 'T' then 'TRAINING'
    else null
  end
$$;

create or replace function staging.legacy_roster_position_role(p_code text)
returns text
language sql immutable set search_path=pg_temp
as $$
  select case p_code
    when 'GO1' then 'GENERAL_OPERATIVE'
    when 'GO2' then 'GENERAL_OPERATIVE'
    when 'GO3' then 'GENERAL_OPERATIVE'
    when 'TL1' then 'TEAM_LEADER'
    when 'TL2' then 'TEAM_LEADER'
    when 'TL3' then 'TEAM_LEADER'
    when 'SA' then 'SORTING_AREA'
    when 'LBL' then 'LABEL'
    when 'SUP' then 'SUPERVISOR'
    when 'CLN' then 'CLEANER'
    when 'SR' then 'SUPPORT_ROLE'
    else null
  end
$$;

create or replace function staging.legacy_roster_position_area(p_code text)
returns text
language sql immutable set search_path=pg_temp
as $$
  select case
    when p_code in ('GO1','GO2','GO3','TL1','TL2','TL3','LBL') then 'FINISH'
    when p_code='SA' then 'SORTING'
    -- The legacy Roster stored these as role-only display sections and did
    -- not persist an Area. V2 requires an area for WORKING/QUALITY_ANALYSIS,
    -- so FINISH is a compatibility value only; the original section remains
    -- authoritative in display_section_code.
    when p_code in ('SUP','CLN','SR') then 'FINISH'
    else null
  end
$$;

create or replace function staging.legacy_roster_position_station(p_code text)
returns text
language sql immutable set search_path=pg_temp
as $$
  select case p_code
    when 'GO1' then 'FINISH_TABLE_1'
    when 'GO2' then 'FINISH_TABLE_2'
    when 'GO3' then 'FINISH_TABLE_3'
    when 'TL1' then 'FINISH_TABLE_1'
    when 'TL2' then 'FINISH_TABLE_2'
    when 'TL3' then 'FINISH_TABLE_3'
    when 'SA' then 'SORTING_MAIN'
    when 'LBL' then 'FINISH_LABEL'
    else null
  end
$$;

create or replace function staging.legacy_roster_display_section(p_code text)
returns text
language sql immutable set search_path=pg_temp
as $$
  select case p_code
    when 'GO1' then 'FINISH_TABLE_1'
    when 'GO2' then 'FINISH_TABLE_2'
    when 'GO3' then 'FINISH_TABLE_3'
    when 'TL1' then 'FINISH_TABLE_1'
    when 'TL2' then 'FINISH_TABLE_2'
    when 'TL3' then 'FINISH_TABLE_3'
    when 'SA' then 'SORTING_AREA'
    when 'LBL' then 'LABEL'
    when 'SUP' then 'SUPERVISOR'
    when 'CLN' then 'CLEANER'
    when 'SR' then 'SUPPORT_ROLE'
    else 'FINISH_OTHER'
  end
$$;

revoke all on function staging.legacy_roster_status(text) from public, anon, authenticated;
revoke all on function staging.legacy_roster_position_role(text) from public, anon, authenticated;
revoke all on function staging.legacy_roster_position_area(text) from public, anon, authenticated;
revoke all on function staging.legacy_roster_position_station(text) from public, anon, authenticated;
revoke all on function staging.legacy_roster_display_section(text) from public, anon, authenticated;

