values ('LEGACY_ROSTER_20260808','Weekly Shift Roster_db (1).xlsx','LR1785934193533451','7f933ce0-40e0-57e9-bf7a-6a5d199817ec'::uuid,23,'Bendita Fernandes','DAY_OFF',date '2026-08-10',date '2026-08-10',null,'2026-08-05T13:49:56.608000+01:00'::timestamptz,'APPROVED','SYSTEM','Legacy roster evidence','2026-08-07T16:11:12.639000+01:00'::timestamptz,'Approved inferred from the saved legacy roster because the exact requested Day Off is recorded as Off; no explicit legacy decision event exists.','ROSTER_INFERRED',false,20,'[{"event_index":1,"occurred_at":"2026-08-05T13:49:56.608000+01:00","event_type":"LEGACY_SUBMITTED","actor_label":"Bendita Fernandes","actor_role":"Staff","from_status":null,"to_status":"PENDING","note":null,"metadata":{"legacy_request_id":"LR1785934193533451","legacy_decision":"Pending","legacy_payload":{"type":"Day Off","startDate":"2026-08-10","endDate":"2026-08-10","durationDays":1}},"event_uuid":"bb138ebb-f9df-57db-aea9-ff4ae632b450"},{"event_index":2,"occurred_at":"2026-08-07T16:11:12.639000+01:00","event_type":"LEGACY_ROSTER_INFERRED_APPROVAL","actor_label":"Legacy roster evidence","actor_role":"System","from_status":"PENDING","to_status":"APPROVED","note":"Approved inferred from the saved legacy roster because the exact requested Day Off is recorded as Off; no explicit legacy decision event exists.","metadata":{"legacy_request_id":"LR1785934193533451","inference_rule":"EXACT_DAY_OFF_MARKED_OFF_WITH_NO_EXPLICIT_DECISION"},"event_uuid":"fce83868-93a8-5b7c-81b9-e1e697446bb4"}]'::jsonb,'[{"work_date":"2026-08-10","status":"Off","week_start":"2026-08-10","shift_code":"EVENING","source_updated_at":"2026-08-07T16:11:12.639000+01:00"}]'::jsonb,null::jsonb)
