values ('LEGACY_ROSTER_20260808','Weekly Shift Roster_db (1).xlsx','LR1785937725253720','3dcf28ba-b514-56bd-9ac8-86d17dfb17b9'::uuid,26,'Vesley Julio M. Fernandes','DAY_OFF',date '2026-08-12',date '2026-08-12',null,'2026-08-05T14:48:47.957000+01:00'::timestamptz,'PENDING',null,null,null::timestamptz,null,'UNRESOLVED',false,20,'[{"event_index":1,"occurred_at":"2026-08-05T14:48:47.957000+01:00","event_type":"LEGACY_SUBMITTED","actor_label":"Vesley Julio M. Fernandes","actor_role":"Staff","from_status":null,"to_status":"PENDING","note":null,"metadata":{"legacy_request_id":"LR1785937725253720","legacy_decision":"Pending","legacy_payload":{"type":"Day Off","startDate":"2026-08-12","endDate":"2026-08-12","durationDays":1}},"event_uuid":"9379a386-abac-5206-aa6c-5ec0c13a222a"}]'::jsonb,'[{"work_date":"2026-08-12","status":"Working","week_start":"2026-08-10","shift_code":"EVENING","source_updated_at":"2026-08-07T16:11:12.639000+01:00"}]'::jsonb,null::jsonb)
on conflict (source_batch,legacy_request_id) do nothing;


-- ---------------------------------------------------------------------
-- Strict staff mapping safety checks.
-- Never create guessed staff members during a history import.
-- ---------------------------------------------------------------------

do $$
declare
  v_missing text;
begin
  with ids as (
    select distinct (e.value->>0)::integer as legacy_user_id
    from staging.legacy_production_roster_source s
    cross join lateral jsonb_array_elements(s.source_payload->'e') e(value)
    where s.source_batch='LEGACY_ROSTER_20260808'
    union
    select distinct legacy_user_id
    from staging.legacy_leave_request_source
    where source_batch='LEGACY_ROSTER_20260808'
  )
  select string_agg(i.legacy_user_id::text, ', ' order by i.legacy_user_id)
  into v_missing
  from ids i
  left join public.staff_members sm
    on sm.legacy_user_id=i.legacy_user_id
   and sm.deleted_at is null
  where sm.staff_id is null;

  if v_missing is not null then
    raise exception 'Legacy history import stopped. Missing Staff Master legacy_user_id mapping(s): %', v_missing;
  end if;
end;
$$;

-- ---------------------------------------------------------------------
-- Reference-data compatibility checks.
-- ---------------------------------------------------------------------

do $$
begin
  if not exists (
    select 1 from public.areas
    where area_code='FINISH' and active=true and deleted_at is null
  ) then
    raise exception 'FINISH area is required for legacy role-only compatibility mapping.';
  end if;

  if exists (
    select 1
    from (values
      ('SUPERVISOR'),
      ('CLEANER'),
      ('SUPPORT_ROLE')
    ) required(role_code)
    left join public.operational_roles r
      on r.role_code=required.role_code
     and r.active=true
     and r.deleted_at is null
    where r.operational_role_id is null
  ) then
    raise exception 'Required legacy role-only operational role reference is missing.';
  end if;
end;
$$;

-- ---------------------------------------------------------------------
-- Import immutable published roster history.
-- Existing V2 published weeks are preserved and skipped.
-- ---------------------------------------------------------------------

do $$
declare
  s staging.legacy_production_roster_source%rowtype;
  v_shift public.shifts%rowtype;
  v_period public.roster_periods%rowtype;
  v_version public.production_roster_versions%rowtype;
  v_version_number integer;
  v_existing uuid;
  v_entry_count integer;
  v_unresolved integer;
  v_role_only_area_fallback_count integer;
begin
  for s in
    select *
    from staging.legacy_production_roster_source
    where source_batch='LEGACY_ROSTER_20260808'
      and import_status='PENDING'
    order by week_start, case shift_code when 'MORNING' then 1 else 2 end
  loop
    perform pg_advisory_xact_lock(hashtext('ELISCARETEXT_LEGACY_ROSTER:'||s.week_start::text||':'||s.shift_code));

    select * into v_shift
    from public.shifts
    where upper(shift_code)=s.shift_code
      and active=true
      and deleted_at is null;

    if not found then
      raise exception 'Active shift % is missing.', s.shift_code;
    end if;

    insert into public.roster_periods (
      week_start,status,published_at,created_at,updated_at
    ) values (
      s.week_start,'PUBLISHED',coalesce(s.source_updated_at,now()),
      coalesce(s.source_updated_at,now()),coalesce(s.source_updated_at,now())
    )
    on conflict (week_start) do nothing;

    select * into v_period
    from public.roster_periods
    where week_start=s.week_start;

    select prv.roster_version_id into v_existing
    from public.production_roster_versions prv
    where prv.roster_period_id=v_period.roster_period_id
      and prv.shift_id=v_shift.shift_id
      and prv.status='PUBLISHED'
    limit 1;

    if v_existing is not null then
      update staging.legacy_production_roster_source
      set import_status='SKIPPED_EXISTING_PUBLISHED',
          imported_roster_version_id=v_existing,
          import_note='Existing V2 published roster preserved; legacy source was not allowed to overwrite it.',
          imported_at=now()
      where source_batch=s.source_batch and week_start=s.week_start and shift_code=s.shift_code;
      continue;
    end if;

    v_version_number:=s.legacy_version;
    if exists (
      select 1 from public.production_roster_versions prv
      where prv.roster_period_id=v_period.roster_period_id
        and prv.shift_id=v_shift.shift_id
        and prv.version_number=v_version_number
    ) then
      select coalesce(max(prv.version_number),0)+1
      into v_version_number
      from public.production_roster_versions prv
      where prv.roster_period_id=v_period.roster_period_id
        and prv.shift_id=v_shift.shift_id;
    end if;

    insert into public.production_roster_versions (
      roster_period_id,shift_id,version_number,status,include_sunday,week_note,
      row_version,saved_at,published_at,created_at,updated_at
    ) values (
      v_period.roster_period_id,v_shift.shift_id,v_version_number,'CANCELLED',s.include_sunday,
      'Imported legacy roster history. Legacy version '||s.legacy_version||
      '; legacy last-save timestamp is retained as the publication-time proxy.',
      1,s.source_updated_at,null,coalesce(s.source_updated_at,now()),coalesce(s.source_updated_at,now())
    )
    returning * into v_version;

    select count(*) into v_role_only_area_fallback_count
    from jsonb_array_elements(s.source_payload->'e') e(value)
    where (e.value->>2) in ('W','Q','C')
      and (e.value->>3) in ('SUP','CLN','SR');

    with
    members as (
      select
        (m.value->>0)::integer as legacy_user_id,
        nullif(m.value->>1,'') as source_name,
        nullif(m.value->>2,'') as weekly_position_code
      from jsonb_array_elements(s.source_payload->'m') m(value)
    ),
    entries as (
      select
        (e.value->>0)::integer as legacy_user_id,
        (e.value->>1)::integer as day_offset,
        e.value->>2 as status_code,
        nullif(e.value->>3,'') as position_code,
        nullif(e.value->>4,'') as cover_code
      from jsonb_array_elements(s.source_payload->'e') e(value)
    ),
    src as (
      select
        m.legacy_user_id,m.source_name,m.weekly_position_code,
        e.day_offset,e.status_code,e.position_code,e.cover_code,
        staging.legacy_roster_status(e.status_code) as day_status,
        case when e.status_code='C' then 'COVER' else 'BASE' end as assignment_type,
        case
          when e.status_code='C' and e.cover_code='TL' then 'TEAM_LEADER'
          when e.status_code='C' and e.cover_code='SP' then 'SUPERVISOR'
          when e.status_code='C' and e.cover_code='SA' then 'SORTING_AREA'
          else staging.legacy_roster_position_role(e.position_code)
        end as role_code,
        case
          when e.status_code='C' and e.cover_code='SA' then 'SORTING'
          else staging.legacy_roster_position_area(e.position_code)
        end as area_code,
        case
          when e.status_code='C' and e.cover_code='SA' then 'SORTING_MAIN'
          else staging.legacy_roster_position_station(e.position_code)
        end as station_code
      from entries e
      join members m using (legacy_user_id)
    ),
    resolved as (
      select
        src.*,
        sm.staff_id,sm.employee_code,sm.display_name,
        sm.fire_training,sm.first_aid_training,sm.eod_capable,
        sm.primary_operational_role_id as current_primary_role_id,
        sm.default_area_id as current_default_area_id,
        sm.default_station_id as current_default_station_id,
        ar.operational_role_id as actual_role_id,
        ar.role_code as actual_role_code,
        ar.role_name as actual_role_name,
        aa.area_id as actual_area_id,
        aa.area_code as actual_area_code,
        aa.area_name as actual_area_name,
        ast.station_id as actual_station_id,
        ast.station_code as actual_station_code,
        ast.station_name as actual_station_name,
        wr.operational_role_id as weekly_role_id,
        wr.role_code as weekly_role_code,
        wr.role_name as weekly_role_name,
        wa.area_id as weekly_area_id,
        wa.area_code as weekly_area_code,
        wa.area_name as weekly_area_name,
        wst.station_id as weekly_station_id,
        wst.station_code as weekly_station_code,
        wst.station_name as weekly_station_name,
        cr.role_code as current_primary_role_code,
        cr.role_name as current_primary_role_name,
        ca.area_code as current_default_area_code,
        ca.area_name as current_default_area_name,
        cst.station_code as current_default_station_code,
        cst.station_name as current_default_station_name
      from src
      join public.staff_members sm
        on sm.legacy_user_id=src.legacy_user_id
       and sm.deleted_at is null
      left join public.operational_roles ar
        on ar.role_code=src.role_code and ar.deleted_at is null
      left join public.areas aa
        on aa.area_code=src.area_code and aa.deleted_at is null
      left join public.stations ast
        on ast.station_code=src.station_code and ast.deleted_at is null
      left join public.operational_roles wr
        on wr.role_code=staging.legacy_roster_position_role(src.weekly_position_code) and wr.deleted_at is null
      left join public.areas wa
        on wa.area_code=staging.legacy_roster_position_area(src.weekly_position_code) and wa.deleted_at is null
      left join public.stations wst
        on wst.station_code=staging.legacy_roster_position_station(src.weekly_position_code) and wst.deleted_at is null
      left join public.operational_roles cr on cr.operational_role_id=sm.primary_operational_role_id
      left join public.areas ca on ca.area_id=sm.default_area_id
      left join public.stations cst on cst.station_id=sm.default_station_id
    )
    select count(*) into v_unresolved
    from resolved r
    where r.day_status in ('WORKING','QUALITY_ANALYSIS')
      and (
        coalesce(r.actual_role_id,r.current_primary_role_id) is null
        or coalesce(r.actual_area_id,r.current_default_area_id) is null
      );

    if v_unresolved>0 then
      raise exception 'Legacy roster % % has % working/quality entries without a safe role/area mapping after compatibility resolution.',
        s.week_start,s.shift_code,v_unresolved;
    end if;

    insert into public.production_roster_entries (
      roster_version_id,work_date,staff_id,day_status,assignment_type,
      operational_role_id,area_id,station_id,planned_start_time,planned_end_time,notes,
      display_section_code,
      staff_display_name_snapshot,employee_code_snapshot,
      shift_code_snapshot,shift_name_snapshot,
      operational_role_code_snapshot,operational_role_name_snapshot,
      area_code_snapshot,area_name_snapshot,station_code_snapshot,station_name_snapshot,
      staff_primary_role_code_snapshot,staff_primary_role_name_snapshot,
      staff_default_area_code_snapshot,staff_default_area_name_snapshot,
      staff_default_station_code_snapshot,staff_default_station_name_snapshot,
      staff_default_shift_code_snapshot,staff_default_shift_name_snapshot,
      fire_training_snapshot,first_aid_training_snapshot,eod_capable_snapshot,
      created_at,updated_at
    )
    with
    members as (
      select
        (m.value->>0)::integer as legacy_user_id,
        nullif(m.value->>1,'') as source_name,
        nullif(m.value->>2,'') as weekly_position_code
      from jsonb_array_elements(s.source_payload->'m') m(value)
    ),
    entries as (
      select
        (e.value->>0)::integer as legacy_user_id,
        (e.value->>1)::integer as day_offset,
        e.value->>2 as status_code,
        nullif(e.value->>3,'') as position_code,
        nullif(e.value->>4,'') as cover_code
      from jsonb_array_elements(s.source_payload->'e') e(value)
    ),
    src as (
      select
        m.legacy_user_id,m.source_name,m.weekly_position_code,
        e.day_offset,e.status_code,e.position_code,e.cover_code,
        staging.legacy_roster_status(e.status_code) as day_status,
        case when e.status_code='C' then 'COVER' else 'BASE' end as assignment_type,
        case
          when e.status_code='C' and e.cover_code='TL' then 'TEAM_LEADER'
          when e.status_code='C' and e.cover_code='SP' then 'SUPERVISOR'
          when e.status_code='C' and e.cover_code='SA' then 'SORTING_AREA'
          else staging.legacy_roster_position_role(e.position_code)
        end as role_code,
        case
          when e.status_code='C' and e.cover_code='SA' then 'SORTING'
          else staging.legacy_roster_position_area(e.position_code)
        end as area_code,
        case
          when e.status_code='C' and e.cover_code='SA' then 'SORTING_MAIN'
          else staging.legacy_roster_position_station(e.position_code)
        end as station_code
      from entries e
      join members m using (legacy_user_id)
    )
    select
      v_version.roster_version_id,
      s.week_start+src.day_offset,
      sm.staff_id,
      src.day_status,
      src.assignment_type,
      case when src.day_status in ('WORKING','QUALITY_ANALYSIS')
        then coalesce(ar.operational_role_id,sm.primary_operational_role_id) end,
      case when src.day_status in ('WORKING','QUALITY_ANALYSIS')
        then coalesce(aa.area_id,sm.default_area_id) end,
      case when src.day_status in ('WORKING','QUALITY_ANALYSIS')
        then case
          when ast.station_id is not null then ast.station_id
          when aa.area_id is null then sm.default_station_id
          else null
        end
      end,
      null,null,null,
      staging.legacy_roster_display_section(src.weekly_position_code),
      coalesce(src.source_name,sm.display_name),sm.employee_code,
      v_shift.shift_code,v_shift.shift_name,
      case when src.day_status in ('WORKING','QUALITY_ANALYSIS')
        then coalesce(ar.role_code,cr.role_code) end,
      case when src.day_status in ('WORKING','QUALITY_ANALYSIS')
        then coalesce(ar.role_name,cr.role_name) end,
      case when src.day_status in ('WORKING','QUALITY_ANALYSIS')
        then coalesce(aa.area_code,ca.area_code) end,
      case when src.day_status in ('WORKING','QUALITY_ANALYSIS')
        then coalesce(aa.area_name,ca.area_name) end,
      case when src.day_status in ('WORKING','QUALITY_ANALYSIS')
        then case when ast.station_id is not null then ast.station_code when aa.area_id is null then cst.station_code else null end end,
      case when src.day_status in ('WORKING','QUALITY_ANALYSIS')
        then case when ast.station_id is not null then ast.station_name when aa.area_id is null then cst.station_name else null end end,
      coalesce(wr.role_code,cr.role_code),
      coalesce(wr.role_name,cr.role_name),
      coalesce(wa.area_code,ca.area_code),
      coalesce(wa.area_name,ca.area_name),
      coalesce(wst.station_code,cst.station_code),
      coalesce(wst.station_name,cst.station_name),
      v_shift.shift_code,v_shift.shift_name,
      sm.fire_training,sm.first_aid_training,sm.eod_capable,
      coalesce(s.source_updated_at,now()),coalesce(s.source_updated_at,now())
    from src
    join public.staff_members sm
      on sm.legacy_user_id=src.legacy_user_id
     and sm.deleted_at is null
    left join public.operational_roles ar on ar.role_code=src.role_code and ar.deleted_at is null
    left join public.areas aa on aa.area_code=src.area_code and aa.deleted_at is null
    left join public.stations ast on ast.station_code=src.station_code and ast.deleted_at is null
    left join public.operational_roles wr
      on wr.role_code=staging.legacy_roster_position_role(src.weekly_position_code) and wr.deleted_at is null
    left join public.areas wa
      on wa.area_code=staging.legacy_roster_position_area(src.weekly_position_code) and wa.deleted_at is null
    left join public.stations wst
      on wst.station_code=staging.legacy_roster_position_station(src.weekly_position_code) and wst.deleted_at is null
    left join public.operational_roles cr on cr.operational_role_id=sm.primary_operational_role_id
    left join public.areas ca on ca.area_id=sm.default_area_id
    left join public.stations cst on cst.station_id=sm.default_station_id;

    select count(*) into v_entry_count
    from public.production_roster_entries
    where roster_version_id=v_version.roster_version_id;

    if v_entry_count<>s.source_entry_count then
      raise exception 'Legacy roster % % entry count mismatch. Expected %, inserted %.',
        s.week_start,s.shift_code,s.source_entry_count,v_entry_count;
    end if;

    update public.production_roster_versions
    set status='PUBLISHED',
        published_at=coalesce(s.source_updated_at,now()),
        saved_at=coalesce(s.source_updated_at,now()),
        week_note='Imported legacy roster history. Legacy version '||s.legacy_version||
          '; legacy last-save timestamp is retained as the publication-time proxy.'
    where roster_version_id=v_version.roster_version_id;

    insert into public.production_roster_events (
      roster_version_id,event_type,reason,metadata,occurred_at
    ) values (
      v_version.roster_version_id,'PUBLISHED',
      'Imported from legacy Weekly Shift Roster workbook as immutable history.',
      jsonb_build_object(
        'source_batch',s.source_batch,
        'source_file',s.source_file,
        'legacy_version',s.legacy_version,
        'legacy_updated_by',s.source_updated_by,
        'legacy_updated_at',s.source_updated_at,
        'publication_timestamp_basis','LEGACY_LAST_SAVE_PROXY',
        'source_entry_count',s.source_entry_count,
        'implicit_default_entries_reconstructed',s.implicit_default_count,
        'training_snapshot_basis','CURRENT_STAFF_MASTER_AT_IMPORT',
        'role_only_area_compatibility',jsonb_build_object(
          'legacy_position_codes',jsonb_build_array('SUP','CLN','SR'),
          'v2_area_code','FINISH',
          'entry_count',v_role_only_area_fallback_count,
          'basis','LEGACY_SOURCE_HAS_NO_AREA_FOR_ROLE_ONLY_SECTION'
        )
      ),
      coalesce(s.source_updated_at,now())
    );

    update staging.legacy_production_roster_source
    set import_status='IMPORTED',
        imported_roster_version_id=v_version.roster_version_id,
        import_note='Imported as immutable PUBLISHED history.',
        imported_at=now()
    where source_batch=s.source_batch and week_start=s.week_start and shift_code=s.shift_code;
  end loop;
end;
$$;

-- ---------------------------------------------------------------------
-- Import legacy leave history and outstanding future requests.
-- ---------------------------------------------------------------------

do $$
declare
  s staging.legacy_leave_request_source%rowtype;
  v_staff public.staff_members%rowtype;
  v_existing uuid;
  v_event jsonb;
  v_gm jsonb;
begin
  for s in
    select *
    from staging.legacy_leave_request_source
    where source_batch='LEGACY_ROSTER_20260808'
      and import_status='PENDING'
    order by submitted_at,legacy_request_id
  loop
    select * into v_staff
    from public.staff_members
    where legacy_user_id=s.legacy_user_id
      and deleted_at is null;

    select prlr.leave_request_id into v_existing
    from public.production_roster_leave_requests prlr
    where prlr.staff_id=v_staff.staff_id
      and prlr.request_type=s.request_type
      and prlr.start_date=s.start_date
      and prlr.end_date=s.end_date
      and prlr.leave_request_id<>s.target_leave_request_id
    order by prlr.submitted_at
    limit 1;

    if v_existing is not null then
      update staging.legacy_leave_request_source
      set import_status='SKIPPED_EXISTING_EQUIVALENT',
          imported_leave_request_id=v_existing,
          import_note='Equivalent V2 leave request already exists; duplicate operational request was not created.',
          imported_at=now()
      where source_batch=s.source_batch and legacy_request_id=s.legacy_request_id;
      continue;
    end if;

    if exists (
      select 1 from public.production_roster_leave_requests
      where leave_request_id=s.target_leave_request_id
    ) then
      update staging.legacy_leave_request_source
      set import_status='ALREADY_IMPORTED',
          imported_leave_request_id=s.target_leave_request_id,
          import_note='Deterministic legacy leave request already exists.',
          imported_at=now()
      where source_batch=s.source_batch and legacy_request_id=s.legacy_request_id;
      continue;
    end if;

    insert into public.production_roster_leave_requests (
      leave_request_id,staff_id,staff_display_name_snapshot,request_type,
      start_date,end_date,reason,status,submitted_at,reviewed_at,review_note,
      source_application,requires_general_manager,gm_threshold_days_snapshot,
      decision_source,decision_actor
    ) values (
      s.target_leave_request_id,v_staff.staff_id,s.staff_name,s.request_type,
      s.start_date,s.end_date,s.reason,s.final_status,s.submitted_at,
      case when s.final_status in ('APPROVED','REJECTED') then s.reviewed_at else null end,
      case when s.final_status in ('APPROVED','REJECTED') then s.review_note else null end,
      'LEGACY_ROSTER_IMPORT',s.requires_general_manager,s.gm_threshold_days_snapshot,
      case when s.final_status in ('APPROVED','REJECTED') then s.decision_source else null end,
      case when s.final_status in ('APPROVED','REJECTED') then s.decision_actor else null end
    );

    for v_event in
      select value
      from jsonb_array_elements(s.source_events)
      order by (value->>'event_index')::integer
    loop
      insert into public.production_roster_leave_request_events (
        leave_event_id,leave_request_id,event_type,actor_label,actor_role,
        from_status,to_status,note,metadata,occurred_at
      ) values (
        (v_event->>'event_uuid')::uuid,
        s.target_leave_request_id,
        v_event->>'event_type',
        nullif(v_event->>'actor_label',''),
        nullif(v_event->>'actor_role',''),
        nullif(v_event->>'from_status',''),
        nullif(v_event->>'to_status',''),
        nullif(v_event->>'note',''),
        coalesce(v_event->'metadata','{}'::jsonb) ||
          jsonb_build_object('source_batch',s.source_batch,'source_file',s.source_file,'decision_basis',s.decision_basis),
        (v_event->>'occurred_at')::timestamptz
      );
    end loop;

    v_gm:=s.gm_review;
    if v_gm is not null and jsonb_typeof(v_gm)='object' then
      insert into public.production_roster_leave_gm_reviews (
        leave_request_id,token_hash,token_hint,sent_to,state,sent_at,expires_at,
        decision,decided_at,decision_note,updated_at
      ) values (
        s.target_leave_request_id,null,null,
        nullif(v_gm->>'sent_to',''),
        coalesce(nullif(v_gm->>'state',''),'DECIDED'),
        nullif(v_gm->>'sent_at','')::timestamptz,
        nullif(v_gm->>'expires_at','')::timestamptz,
        nullif(v_gm->>'decision',''),
        nullif(v_gm->>'decided_at','')::timestamptz,
        nullif(v_gm->>'decision_note',''),
        coalesce(nullif(v_gm->>'decided_at','')::timestamptz,now())
      )
      on conflict (leave_request_id) do nothing;
    end if;

    update staging.legacy_leave_request_source
    set import_status='IMPORTED',
        imported_leave_request_id=s.target_leave_request_id,
        import_note=case
          when s.decision_basis='ROSTER_INFERRED'
            then 'Imported with explicitly labelled roster-evidence inference.'
          else 'Imported from explicit legacy request/audit history.'
        end,
        imported_at=now()
    where source_batch=s.source_batch and legacy_request_id=s.legacy_request_id;
  end loop;
end;
$$;

insert into public.audit_log (
  action,entity_table,entity_id,new_data,reason,source_application,occurred_at
) values (
  'LEGACY_PRODUCTION_ROSTER_AND_LEAVE_HISTORY_IMPORTED',
  'staging.legacy_production_roster_source',
  'LEGACY_ROSTER_20260808',
  jsonb_build_object(
    'source_file','Weekly Shift Roster_db (1).xlsx',
    'historical_roster_snapshots',50,
    'historical_weeks',25,
    'historical_entries',8186,
    'implicit_default_entries_reconstructed',788,
    'leave_requests',57,
    'leave_expected_statuses',jsonb_build_object('APPROVED',41,'REJECTED',8,'PENDING',8),
    'roster_inferred_leave_approvals',2,
    'legacy_roster_revision_rows_not_promoted_to_official_versions',400,
    'legacy_gm_config_changes_not_applied',3
  ),
  'Controlled legacy history migration; existing V2 published rosters and equivalent leave requests were preserved.',
  'LEGACY_ROSTER_IMPORT',
  now()
);

commit;
